function animate() {
  const dt = clock.getDelta();
  const moveX = (keys['d'] || keys['arrowright'] ? 1 : 0) - (keys['a'] || keys['arrowleft'] ? 1 : 0) + touchMove.x;
  const moveZ = (keys['w'] || keys['arrowup'] ? 1 : 0) - (keys['s'] || keys['arrowdown'] ? 1 : 0) - touchMove.y;

  if (moveX || moveZ) {
    const inputMagnitude = Math.min(1, Math.hypot(moveX, moveZ));
    const dir = new THREE.Vector3(moveX, 0, moveZ).normalize();
    const speed = (keys['shift'] ? 1.5 : 1) * player.speed * inputMagnitude;
    player.group.position.x += dir.x * speed * dt;
    player.group.position.z += dir.z * speed * dt;
    player.group.position.x = clampNumber(player.group.position.x, -18, 18);
    player.group.position.z = clampNumber(player.group.position.z, -18, 18);
  }

  player.group.rotation.y = Math.atan2(cameraOrbit.yaw, 1) + Math.PI * 0.15;

  state.enemies.forEach((enemy, idx) => {
    enemy.position.x += Math.sin(clock.elapsedTime * (0.8 + idx * 0.15) + enemy.userData.drift) * 0.02;
    enemy.position.z += Math.cos(clock.elapsedTime * (0.7 + idx * 0.18) + enemy.userData.drift) * 0.02;
    enemy.position.x = clampNumber(enemy.position.x, -18, 18);
    enemy.position.z = clampNumber(enemy.position.z, -18, 18);
  });

  cameraTarget.copy(player.group.position).add(new THREE.Vector3(0, 1.8, 0));
  const cosYaw = Math.cos(cameraOrbit.yaw);
  const sinYaw = Math.sin(cameraOrbit.yaw);
  const cameraOffset = new THREE.Vector3(cosYaw * cameraOrbit.distance, 7.5 + Math.sin(cameraOrbit.pitch) * 2.8, sinYaw * cameraOrbit.distance);
  const desired = cameraTarget.clone().add(cameraOffset);
  camera.position.lerp(desired, 0.08);
  camera.lookAt(cameraTarget);

  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

input.newString:
function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const moveX = (keys['d'] || keys['arrowright'] ? 1 : 0) - (keys['a'] || keys['arrowleft'] ? 1 : 0) + touchMove.x;
  const moveZ = (keys['w'] || keys['arrowup'] ? 1 : 0) - (keys['s'] || keys['arrowdown'] ? 1 : 0) - touchMove.y;
  const inputLength = Math.hypot(moveX, moveZ);
  const inputMagnitude = Math.min(1, inputLength);

  if (inputLength > 0.001) {
    movementDirection.set(moveX / inputLength, 0, moveZ / inputLength);
    const speed = player.speed * (keys['shift'] ? 1.5 : 1) * inputMagnitude;
    player.velocity.x = movementDirection.x * speed;
    player.velocity.z = movementDirection.z * speed;
    player.group.position.x += player.velocity.x * dt;
    player.group.position.z += player.velocity.z * dt;
    player.group.position.x = clampNumber(player.group.position.x, -18, 18);
    player.group.position.z = clampNumber(player.group.position.z, -18, 18);
    const targetYaw = Math.atan2(movementDirection.x, movementDirection.z);
    let yawDelta = targetYaw - player.group.rotation.y;
    yawDelta = Math.atan2(Math.sin(yawDelta), Math.cos(yawDelta));
    player.group.rotation.y += yawDelta * (1 - Math.exp(-12 * dt));
  } else {
    player.velocity.set(0, 0, 0);
  }

  const time = clock.elapsedTime;
  state.enemies.forEach((enemy, idx) => {
    enemy.position.x += Math.sin(time * (0.8 + idx * 0.15) + enemy.userData.drift) * 0.02;
    enemy.position.z += Math.cos(time * (0.7 + idx * 0.18) + enemy.userData.drift) * 0.02;
    enemy.position.x = clampNumber(enemy.position.x, -18, 18);
    enemy.position.z = clampNumber(enemy.position.z, -18, 18);
  });

  desiredCameraTarget.set(player.group.position.x, player.group.position.y + 1.3, player.group.position.z);
  const horizontalDistance = Math.cos(cameraOrbit.pitch) * cameraOrbit.distance;
  desiredCameraPosition.set(
    desiredCameraTarget.x + Math.cos(cameraOrbit.yaw) * horizontalDistance,
    desiredCameraTarget.y + Math.sin(cameraOrbit.pitch) * cameraOrbit.distance,
    desiredCameraTarget.z + Math.sin(cameraOrbit.yaw) * horizontalDistance
  );
  const cameraFollow = 1 - Math.exp(-7 * dt);
  cameraTarget.lerp(desiredCameraTarget, cameraFollow);
  camera.position.lerp(desiredCameraPosition, cameraFollow);
  camera.lookAt(cameraTarget);

  renderer.render(scene, camera);
}

